INSERT INTO `wp_posts` VALUES (363,1,'2026-02-08 21:12:41','2026-02-08 21:12:41','<!-- wp:acf/page-heading {\"name\":\"acf/page-heading\",\"data\":{\"title\":\"\\u003ch1\\u003eMicrolearning Video Solutions\\u003c/h1\\u003e\",\"_title\":\"field_699a0f54e75a3\",\"description\":\"Statistics have proven that while the need for effective eLearning is increasing, the attention span of most humans is on the decline.\\r\\n\\r\\nHow do we combat both concerns?? \\u003cstrong\\u003eMicrolearning Solutions.\\u003c/strong\\u003e\\r\\n\\r\\nMicrolearning solutions are methods that include short educational spurts in video format to both entertain and educate a growing workforce or student population — optimizing downtime and productivity rates for every booming business.\",\"_description\":\"field_699a0f65e75a4\",\"image\":905,\"_image\":\"field_699a0f73e75a5\",\"link_1\":{\"title\":\"Check out our work!\",\"url\":\"/elearning-video-portfolio/\",\"target\":\"\"},\"_link_1\":\"field_699a0f7ee75a6\",\"link_2\":{\"title\":\"Get a Quote!\",\"url\":\"/elearning-video-animation-companies-free-consultation/\",\"target\":\"\"},\"_link_2\":\"field_699a0f96e75a7\",\"right_to_left\":\"0\",\"_right_to_left\":\"field_699a0f9de75a8\",\"design\":\"simple\",\"_design\":\"field_699a0fefe75a9\"},\"mode\":\"preview\"} /-->\n\n<!-- wp:spacer {\"height\":\"4rem\"} -->\n<div style=\"height:4rem\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:acf/video-block {\"name\":\"acf/video-block\",\"data\":{\"right_to_left\":\"0\",\"_right_to_left\":\"field_69ac28bd57647\",\"design\":\"mesh\",\"_design\":\"field_69ac290257648\",\"title\":\"What is a Microlearning Video?\",\"_title\":\"field_6976d60a207b6\",\"content\":\"Microlearning solutions use video to combine hyper-focused content, stunning animation, and exciting audio to produce an eLearning method that works for every student. Slide decks are a thing of the past and just don?t offer the same benefits and desired outcome ? if they even finish it? at all!\\r\\n\\r\\nWith microlearning solutions, less is definitely more ? more engagement, more output? more RESULTS!\",\"_content\":\"field_6976d622207b7\",\"link\":{\"title\":\"Get in Touch\",\"url\":\"/contact-us/\",\"target\":\"\"},\"_link\":\"field_6976d62a207b8\",\"video\":\"https://vimeo.com/727563749?fl=pl\\u0026fe=sh\",\"_video\":\"field_6976d638207b9\",\"thumbnail\":\"\",\"_thumbnail\":\"field_697abd828e0bf\"},\"mode\":\"preview\"} /-->\n\n<!-- wp:acf/grid-items {\"name\":\"acf/grid-items\",\"data\":{\"title\":\"Our Work\",\"_title\":\"field_6977a3f378dce\",\"description\":\"Animation, live action, graphic storytelling, and captivating narratives combine to revolutionize the eLearning corporate training industry ? it?s just what we do. Check out some of our proud customers!\",\"_description\":\"field_6977a40278dcf\",\"items_0_tag\":\"\",\"_items_0_tag\":\"field_69a6591724e81\",\"items_0_title\":\"AT\\u0026T\",\"_items_0_title\":\"field_6977a41d78dd1\",\"items_0_image\":907,\"_items_0_image\":\"field_6977a42478dd2\",\"items_0_link\":{\"title\":\"\",\"url\":\"http://localhost:8080/projects/att-2/\",\"target\":\"\"},\"_items_0_link\":\"field_6977a42d78dd3\",\"items_1_tag\":\"\",\"_items_1_tag\":\"field_69a6591724e81\",\"items_1_title\":\"The Wonderful Company\",\"_items_1_title\":\"field_6977a41d78dd1\",\"items_1_image\":908,\"_items_1_image\":\"field_6977a42478dd2\",\"items_1_link\":{\"title\":\"\",\"url\":\"http://localhost:8080/projects/the-wonderful-company-2/\",\"target\":\"\"},\"_items_1_link\":\"field_6977a42d78dd3\",\"items_2_tag\":\"\",\"_items_2_tag\":\"field_69a6591724e81\",\"items_2_title\":\"ARA (American Rental Association)\",\"_items_2_title\":\"field_6977a41d78dd1\",\"items_2_image\":909,\"_items_2_image\":\"field_6977a42478dd2\",\"items_2_link\":{\"title\":\"\",\"url\":\"http://localhost:8080/projects/american-rental-association/\",\"target\":\"\"},\"_items_2_link\":\"field_6977a42d78dd3\",\"items\":3,\"_items\":\"field_6977a40c78dd0\"},\"mode\":\"preview\"} /-->\n\n<!-- wp:spacer {\"height\":\"6rem\"} -->\n<div style=\"height:6rem\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {\"verticalAlignment\":\"center\",\"className\":\"container\"} -->\n<div class=\"wp-block-columns are-vertically-aligned-center container\"><!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Our <em>Case Studies<br></em></h2>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"3rem\"} -->\n<div style=\"height:3rem\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">San Diego Zoo</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>High Detail Illustrative + Character</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Loved by children and adults across the globe, the famous San Diego Zoo wanted to create live-action videos featuring their amazing staff scientists on the subject of plant propagation. A tough subject to film, the San Diego Zoo reached out to the experts at Ninja Tropic to handle the job. Animating the staff and explanation, the eLearning modules featured the voice of the scientific explainer videos and were praised by all. The zoo even came back to Ninja Tropic for more!<br></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/case-studies/\">Show more</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n\n<!-- wp:spacer {\"height\":\"3rem\"} -->\n<div style=\"height:3rem\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Engagedly</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Infographic + Live Action</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Performance management is the forte of Engagedly, but when it came to implementing an eLearning solution that actually performed, they came to us. Engagedly needed a learning strategy for potential customers focused on mentorship and combining polished live action clips with beautiful animation was the perfect solution. At the end of the project, Engagedly had a collection of purposeful content for their subscribers to boost their corporate cultures through advisorship.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/case-studies/engagedly-mentorship-elearning/\">Show more</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n\n<!-- wp:spacer {\"height\":\"3rem\"} -->\n<div style=\"height:3rem\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Old Castle</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>High detail Illustrative + 3D</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Procedural training is a challenging feat because traditional instructional methods struggle to keep attention. The experts at Oldcastle Infrastructure veered away from the ?normal slide deck? and opted for animated 3D training to visually demonstrate a new process to their line employees that they could access anytime. Oldcastle?s team connected instantly to the video and were able to implement the new complex process successfully.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/case-studies/oldcastle-3d-safety-training/\">Show more</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\"><!-- wp:image {\"id\":912,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost:8080/wp-content/uploads/2026/03/MS_Our-case-studies-526x1024.webp\" alt=\"\" class=\"wp-image-912\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {\"height\":\"6rem\"} -->\n<div style=\"height:6rem\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\"><strong>Related </strong><em><strong>Solutions<br></strong></em></h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns {\"className\":\"container\"} -->\n<div class=\"wp-block-columns container\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":785,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full\"><img src=\"http://localhost:8080/wp-content/uploads/2026/03/Video-Training-Strategy-2.webp\" alt=\"\" class=\"wp-image-785\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"level\":4,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\">Video Training Strategy</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\">Looking for eLearning solutions on the go? Mobile Learning is the answer! It offers the flexibility to learn anytime, anywhere, allowing your team to learn on their own terms.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"className\":\"alt\"} -->\n<div class=\"wp-block-button alt\"><a class=\"wp-block-button__link wp-element-button\" href=\"/learning-solutions/video-training-strategy/\">Learn more</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":915,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full\"><img src=\"http://localhost:8080/wp-content/uploads/2026/03/Custom-Development-Training.webp\" alt=\"\" class=\"wp-image-915\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"level\":4,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\">Custom<br>Development Training</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\">When learners visualize themselves in relevant scenarios, scenario-based video eLearning enhances understanding and promotes effective implementation. It?s ideal for hands-on learners!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"className\":\"alt\"} -->\n<div class=\"wp-block-button alt\"><a class=\"wp-block-button__link wp-element-button\" href=\"/learning-solutions/custom-elearning-development-services/\">Learn more</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":786,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full\"><img src=\"http://localhost:8080/wp-content/uploads/2026/03/Corporate-Training.webp\" alt=\"\" class=\"wp-image-786\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"level\":4,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\">Corporate Training</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\">Got a few minutes between meetings? Struggling to fit in mandatory training? With demanding schedules, Microlearning solutions from Ninja Tropic offer the condensed learning you need!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"className\":\"alt\"} -->\n<div class=\"wp-block-button alt\"><a class=\"wp-block-button__link wp-element-button\" href=\"/corporate-training/\">Learn more</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {\"height\":\"6rem\"} -->\n<div style=\"height:6rem\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:acf/hubspot-form {\"name\":\"acf/hubspot-form\",\"data\":{\"title\":\"Get a [gradient]FREE Consultation[/gradient] With Ninja Tropic!\",\"_title\":\"field_697ad122e258a\",\"description\":\"Are you aware of the sheer power of engaging eLearning solutions but not sure where to start? Schedule a?\\u003cstrong\\u003efree 30-minute consultation\\u003c/strong\\u003e?with a Ninja Tropic eLearning expert to analyze your organization?s content objectives and map out the interactive blueprint to achieve them.\",\"_description\":\"field_697ad133e258b\",\"form\":\"\\u003cscript charset=\\u0022utf-8\\u0022 type=\\u0022text/javascript\\u0022 src=\\u0022//js.hsforms.net/forms/embed/v2.js\\u0022\\u003e\\u003cspan data-mce-type=\\u0022bookmark\\u0022 style=\\u0022display: inline-block; width: 0px; overflow: hidden; line-height: 0;\\u0022 class=\\u0022mce_SELRES_start\\u0022\\u003e?\\u003c/span\\u003e\\u003cspan data-mce-type=\\u0022bookmark\\u0022 style=\\u0022display: inline-block; width: 0px; overflow: hidden; line-height: 0;\\u0022 class=\\u0022mce_SELRES_start\\u0022\\u003e?\\u003c/span\\u003e\\u003cspan data-mce-type=\\u0022bookmark\\u0022 style=\\u0022display: inline-block; width: 0px; overflow: hidden; line-height: 0;\\u0022 class=\\u0022mce_SELRES_start\\u0022\\u003e?\\u003c/span\\u003e\\u003cspan data-mce-type=\\u0022bookmark\\u0022 style=\\u0022display: inline-block; width: 0px; overflow: hidden; line-height: 0;\\u0022 class=\\u0022mce_SELRES_start\\u0022\\u003e?\\u003c/span\\u003e\\u003cspan data-mce-type=\\u0022bookmark\\u0022 style=\\u0022display: inline-block; width: 0px; overflow: hidden; line-height: 0;\\u0022 class=\\u0022mce_SELRES_start\\u0022\\u003e?\\u003c/span\\u003e\\u003c/script\\u003e\\r\\n\\u003cscript\\u003e\\r\\n  hbspt.forms.create({\\r\\n    region: \\u0022na1\\u0022,\\r\\n    portalId: \\u00227816367\\u0022,\\r\\n    formId: \\u0022394c2aa7-ab2d-43b4-8cf2-d230dd4662bf\\u0022\\r\\n  });\\r\\n\\u003c/script\\u003e\",\"_form\":\"field_697ad143e258c\"},\"mode\":\"preview\"} /-->','Microlearning Solutions | Video Elearning and Video Animation Company.','','publish','closed','closed','','microlearning-solutions','','','2026-06-28 00:26:28','2026-06-28 00:26:28','',333,'http://localhost:8080/?page_id=363',0,'page','',0);
